CREATE PROCEDURE [dbo].[Actualizar_Producto]
    @No NVARCHAR(20),
    @Description NVARCHAR(100),
    @Unit_Price DECIMAL(18,2),
    @VAT_Prod_Posting_Group NVARCHAR(20),
    @Gas_Station_Code NVARCHAR(10)

AS
BEGIN
    SET NOCOUNT ON;
    
    BEGIN TRY
        BEGIN TRANSACTION;
        
        -- Actualizar en la tabla Item
        UPDATE [dbo].[Item]
        SET 
            [Description] = @Description,
            [Unit Price] = @Unit_Price,
            [VAT Prod_ Posting Group] = @VAT_Prod_Posting_Group
        WHERE [No_] = @No;

        -- Actualizar en la tabla Sales Price
        UPDATE [dbo].[Sales Price]
        SET 
            [Unit Price] = @Unit_Price
        WHERE [Item No_] = @No
          AND [Gas Station Code] = @Gas_Station_Code;

        -- Confirmar transacción si todo salió bien
        COMMIT TRANSACTION;

        -- Retornar un mensaje de éxito
        SELECT 'Éxito' AS Resultado, 'Producto y precio actualizados correctamente' AS Mensaje;
    END TRY
    BEGIN CATCH
        -- Revertir cambios en caso de error
        ROLLBACK TRANSACTION;

        -- Retornar mensaje de error
        SELECT 'Error' AS Resultado, ERROR_MESSAGE() AS Mensaje;
    END CATCH
END;

/* Procedimiento de merge */
CREATE   PROCEDURE [dbo].[BulkInsertItemReferences]
    @MergeStatus INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRAN;

        MERGE dbo.ItemReferences AS Target
        USING dbo.Temp_ItemReference AS Source
           ON Target.Item_No         = Source.Item_No
          AND Target.Unit_of_Measure = Source.Unit_of_Measure
          AND Target.Reference_Type  = Source.Reference_Type
          AND Target.Reference_No    = Source.Reference_No
        WHEN MATCHED THEN
            UPDATE SET
                Target.OdataEtag   = Source.OdataEtag,
                Target.Description = Source.Description
        WHEN NOT MATCHED BY TARGET THEN
            INSERT (
                OdataEtag,
                Item_No,
                Unit_of_Measure,
                Reference_Type,
                Reference_No,
                Description
            )
            VALUES (
                Source.OdataEtag,
                Source.Item_No,
                Source.Unit_of_Measure,
                Source.Reference_Type,
                Source.Reference_No,
                Source.Description
            )
        WHEN NOT MATCHED BY SOURCE THEN
            DELETE;

        SET @MergeStatus = @@ROWCOUNT;

        TRUNCATE TABLE dbo.Temp_ItemReference;

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;

        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();

        RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END;

create PROCEDURE [dbo].[ChangeClient]
    @NewCustomerforInvoice VARCHAR(50),
    @NewRTNforInvoice VARCHAR(50),
    @NumeroTransaccionForUpdate VARCHAR(50),
    @Status INT OUTPUT -- Parámetro de salida
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @OldCustomer VARCHAR(50);
    DECLARE @OldRTN VARCHAR(50);

    -- Obtener valores antiguos de la cabecera de ventas
    SELECT @OldCustomer = [Cust_ Name],  
           @OldRTN = [Customer No_]
    FROM [POS Sales Header]
    WHERE [POS Transaction ID] = @NumeroTransaccionForUpdate;

    -- Validar que los datos antiguos existan antes de continuar
    IF @OldCustomer IS NOT NULL AND @OldRTN IS NOT NULL
    BEGIN
        -- Insertar el registro de modificaciones
        INSERT INTO [ModificationsRecords]
                   ([Modifications]
                   ,[POS Transaction ID])
        VALUES
                   (
                       CONCAT(
                           'OLD Customer: ', @OldCustomer, 
                           ' | OLD RTN: ', @OldRTN, 
                           ' | NEW Customer: ', @NewCustomerforInvoice, 
                           ' | NEW RTN: ', @NewRTNforInvoice
                       ), 
                       @NumeroTransaccionForUpdate
                   );

        -- Actualizar la cabecera de ventas
        UPDATE [POS Sales Header]
        SET [Customer No_] = @NewRTNforInvoice, 
            [VAT Reg_ No_] = @NewRTNforInvoice, 
            [Cust_ Name] = @NewCustomerforInvoice
        WHERE [POS Transaction ID] = @NumeroTransaccionForUpdate;

        -- Operación exitosa
        SET @Status = 1;
    END
    ELSE
    BEGIN
        -- No se encontraron datos
        SET @Status = 0;
    END
END;

CREATE PROCEDURE [dbo].[CloseShiftAndCreateNew]
