PRINT 'Turno válido y no existente en [POS Closed Shift]. Procediendo con el cierre del turno anterior.';



  -- Paso 4: Actualizar turno cerrado
        PRINT 'Paso 3: Cerrando turno ' + @OldPOSTransactionID;
