create PROCEDURE [dbo].[CloseShiftInsertNew]
    @IdWeekDay INT,
    @numeroPos NVARCHAR(5),
    @StoreID NVARCHAR(5),
    @CurrentDate DATE,
    @idWeekDayOut INT OUTPUT,
    @weekDayOut NVARCHAR(20) OUTPUT,
    @shiftNameOut NVARCHAR(50) OUTPUT,
    @levelOut INT OUTPUT,
    @ShiftDateOut DATE OUTPUT,
    @StatusCode INT OUTPUT,
    @ErrorMessage NVARCHAR(255) OUTPUT
AS
BEGIN
    BEGIN TRY
        -- Inicializar variables de salida
        SET @idWeekDayOut = NULL;
        SET @weekDayOut = NULL;
        SET @shiftNameOut = NULL;
        SET @levelOut = NULL;
        SET @ShiftDateOut = NULL;
        SET @StatusCode = 0;
        SET @ErrorMessage = NULL;

        DECLARE @CurrentLevel INT;
        DECLARE @NextLevel INT = 0;
        DECLARE @CurrentDay NVARCHAR(20);
        DECLARE @SystemDay NVARCHAR(20) = (SELECT UPPER(FORMAT(GETDATE(), 'dddd', 'es-ES')));
        DECLARE @SystemDate DATE = CONVERT(DATE, GETDATE());

        -- Validar existencia de configuración para el turno actual
        IF NOT EXISTS (
            SELECT 1
            FROM [StoreShiftConfiguration]
            WHERE idWeekDay = @IdWeekDay AND [idStore] = @StoreID AND [posCode] = @numeroPos
        )
        BEGIN
            SET @StatusCode = -1;
            SET @ErrorMessage = 'No se encontró configuración para el turno actual.';
            RETURN;
        END;

        -- Obtener el nivel actual del turno
        SELECT @CurrentLevel = [level]
        FROM [StoreShiftConfiguration]
        WHERE idWeekDay = @IdWeekDay AND [idStore] = @StoreID AND [posCode] = @numeroPos;

        -- Obtener el día del turno actual
        SELECT @CurrentDay = [weekDay]
        FROM [StoreShiftConfiguration]
        WHERE idWeekDay = @IdWeekDay AND [idStore] = @StoreID AND [posCode] = @numeroPos;

        -- Determinar el siguiente nivel
        IF @CurrentDay = @SystemDay AND @CurrentDate = @SystemDate
        BEGIN
            SELECT TOP 1 @NextLevel = level
            FROM [StoreShiftConfiguration]
            WHERE level > @CurrentLevel AND [idStore] = @StoreID AND [posCode] = @numeroPos AND isActive = 1
            ORDER BY level ASC;

            IF @NextLevel = 0
            BEGIN
                SELECT TOP 1 @NextLevel = level
                FROM [StoreShiftConfiguration]
                WHERE level = 1 AND [idStore] = @StoreID AND [posCode] = @numeroPos AND isActive = 1
                ORDER BY level ASC;
            END;
        END
        ELSE
        BEGIN
            SELECT TOP 1 @NextLevel = MIN(level)
            FROM [StoreShiftConfiguration]
            WHERE weekDay = @SystemDay AND [idStore] = @StoreID AND [posCode] = @numeroPos AND isActive = 1;
        END;

        -- Validar si se encontró un nivel
        IF @NextLevel IS NULL
        BEGIN
            SET @StatusCode = -2;
            SET @ErrorMessage = 'No se encontró un siguiente nivel válido.';
            RETURN;
        END;

        -- Asignar los valores del siguiente turno a las variables de salida
        SELECT TOP 1
            @idWeekDayOut = idWeekDay,
            @weekDayOut = weekDay,
            @shiftNameOut = shiftName,
            @levelOut = level,
            @ShiftDateOut = @SystemDate
        FROM [StoreShiftConfiguration]
        WHERE level = @NextLevel AND [idStore] = @StoreID AND [posCode] = @numeroPos AND isActive = 1;

        -- Validar si se encontraron datos
        IF @idWeekDayOut IS NULL OR @weekDayOut IS NULL
        BEGIN
            SET @StatusCode = -3;
            SET @ErrorMessage = 'No se encontraron datos para el siguiente turno.';
            RETURN;
        END;

        -- Intentar insertar en la tabla POS Transaction
        BEGIN TRY
            INSERT INTO [POS Transaction] (
                [ID], [Gas Station Code], [POS Code], [Shift], [idWeekDay], [Shift Starting], [Shift Ending], [ImporteContado]
            )
            VALUES (
                NEWID(), @StoreID, @numeroPos, @shiftNameOut, @idWeekDayOut, @SystemDate, NULL, NULL
            );
        END TRY
        BEGIN CATCH
            -- Capturar errores de inserción
            SET @StatusCode = ERROR_NUMBER();
            SET @ErrorMessage = 'Error al insertar en POS Transaction: ' + ERROR_MESSAGE();
            RETURN;
        END CATCH;

        -- Establecer éxito
        SET @StatusCode = 1;
        SET @ErrorMessage = 'Ejecución exitosa.';
    END TRY
    BEGIN CATCH
        -- Capturar errores generales
        SET @StatusCode = ERROR_NUMBER();
        SET @ErrorMessage = ERROR_MESSAGE();
    END CATCH;
END;

CREATE PROCEDURE [dbo].[CloseShiftV2]
    @numeroPos NVARCHAR(5),
    @StoreID NVARCHAR(5),
    @OldPOSTransactionID NVARCHAR(50),
    @EmployeeName NVARCHAR(50),
    @OldTransactionDateTime DATETIME,
    @OldShiftNumber NVARCHAR(5)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRANSACTION;

    BEGIN TRY
        IF NOT EXISTS (
            SELECT 1 
            FROM [POS Closed Shift] 
            WHERE [POS Transaction ID] = @OldPOSTransactionID
              AND [Gas Station Code] = @StoreID
              AND [EmployeeName] = @EmployeeName
              AND [Shift Ending] IS NULL
        )
        BEGIN
            PRINT 'No se encontró un turno abierto para cerrar.';
            ROLLBACK TRANSACTION;
            SELECT 0 AS Success; 
            RETURN;
        END;

        UPDATE [POS Closed Shift]
        SET [Shift Ending] = GETDATE(),
            [ImporteContado] = 0
        WHERE [POS Transaction ID] = @OldPOSTransactionID
          AND [Gas Station Code] = @StoreID
          AND [EmployeeName] = @EmployeeName
          AND [Shift Ending] IS NULL;

        IF @@ROWCOUNT = 0
        BEGIN
            PRINT 'Error al cerrar el turno. Ya fue cerrado.';
            ROLLBACK TRANSACTION;
            SELECT 0 AS Success; 
            RETURN;
        END;

        INSERT INTO [dbo].[POS Transaction Log]
           ([POS Transaction ID], [Gas Station Code], [POS Code], 
            [Shift Date], [Shift No_], [Transaction Type], [Transaction DateTime], [EmployeeName], [Status])
        VALUES
          (@OldPOSTransactionID, @StoreID, @numeroPos, 
            CONVERT(date,  @OldTransactionDateTime), @OldShiftNumber,
            4, GETDATE(), @EmployeeName, 0);

        COMMIT TRANSACTION;

        SELECT 1 AS Success; 
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;
        PRINT ERROR_MESSAGE(); 
        SELECT 0 AS Success; 
    END CATCH
END;

CREATE PROCEDURE [dbo].[CreateNewCustomer]
    @No NVARCHAR(50),
    @Name NVARCHAR(100),
    @Address NVARCHAR(255),
    @City NVARCHAR(100),
    @PhoneNo NVARCHAR(50),
    @CustomerDiscGroup NVARCHAR(50),
    @CountryRegionCode NVARCHAR(10),
    @Blocked NVARCHAR(10),
    @VATRegistrationNo NVARCHAR(50),
    @PostCode NVARCHAR(20),
    @County NVARCHAR(100),
    @Email NVARCHAR(100),
    @UsualBillingType NVARCHAR(50),
    @Status NVARCHAR(50),
    @CustomerPROMGroup NVARCHAR(50),
    @bcid NVARCHAR(50),
	@DateOfBirth DATE,
	@IdDepartamento int,
	@IdMunicipio int,
    @ReturnStatus INT OUTPUT  -- Parámetro de salida
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        -- Verificar si el cliente ya existe
        IF EXISTS (SELECT 1 FROM [Customer] WHERE [No_] = @No)
        BEGIN
            -- Lanzar una excepción personalizada
            THROW 50001, 'El cliente con el número especificado ya existe.', 1;
        END
        ELSE
        BEGIN
            -- Si no existe, insertar un nuevo registro
            INSERT INTO [Customer]
                ([No_], [Name], [Address], [City], [Phone No_], [Customer Disc_ Group], 
                 [Country_Region Code], [Blocked], [VAT Registration No_], [Post Code], 
                 [County], [E-Mail], [Usual Billing Type], [Status], 
                 [Customer PROM Group], [Update Type], [DateUpdate], [bcid], [DateOfBirth], [IdDepartamento],[IdMunicipio] )
            VALUES
                (@No, @Name, @Address, @City, @PhoneNo, @CustomerDiscGroup, 
                 @CountryRegionCode, @Blocked, @VATRegistrationNo, @PostCode, 
                 @County, @Email, @UsualBillingType, @Status, 
                 @CustomerPROMGroup, NULL, GETDATE(), @bcid, @DateOfBirth, @IdDepartamento, @IdMunicipio);

            -- Establecer el parámetro de salida en éxito
            SET @ReturnStatus = 1;
        END
    END TRY
    BEGIN CATCH
        -- Capturar y re-lanzar cualquier error
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR (@ErrorMessage, 16, 1);
        
        -- Establecer el parámetro de salida en fracaso
        SET @ReturnStatus = 0;
    END CATCH
END

