CREATE PROCEDURE [dbo].[EIInsertCashEntries]
    @GasStationCode NVARCHAR(50),
    @POSCode NVARCHAR(50),
	@ChargeMethodCode NVARCHAR(50),
    @POSSalesDocType NVARCHAR(50),
	@ChargeMethodDescription NVARCHAR(50),
    @Amount DECIMAL(10, 2),
    @SalespersonCode NVARCHAR(50),
	@CustomerNo NVARCHAR(50),
	@Comment NVARCHAR(400),
	@FechaTurno DATE,
	@Turno INT

	AS
	BEGIN
	--//OBTENIENDO NUMERO DE TRANSACCION
	DECLARE @SeriesCodeOfPosTransactionIDNumber NVARCHAR(50);
	DECLARE @LineNoOfPosTransactionIDNumber INT;
	DECLARE @NextPosTransactionIDNumber NVARCHAR(50);

	IF OBJECT_ID('tempdb..#TempResults') IS NOT NULL
		DROP TABLE #TempResults;

	CREATE TABLE #TempResults (
		SeriesCode NVARCHAR(50),
		[LineNo] INT,
		NextPosTransactionIDNumber NVARCHAR(50)
	);

	INSERT INTO #TempResults
	EXEC [dbo].[EINextPosTransactionIDNumber] @GasStationCode, @POSCode;

    -- INSERTO EN VARIABLES
	SELECT TOP 1
		@SeriesCodeOfPosTransactionIDNumber = SeriesCode,
		@LineNoOfPosTransactionIDNumber = [LineNo],
		@NextPosTransactionIDNumber = NextPosTransactionIDNumber
	FROM #TempResults;
	DROP TABLE #TempResults;

	-- Asignar el valor de NextPosTransactionIDNumber a @POSTransactionID
    DECLARE @POSTransactionID NVARCHAR(50);
    SET @POSTransactionID = @NextPosTransactionIDNumber;
	-----------------------------

--//OBTENIENDO NUMERO DE FACTURA
	IF OBJECT_ID('tempdb..#TempInvoiceInfo') IS NOT NULL
    DROP TABLE #TempInvoiceInfo;

	CREATE TABLE #TempInvoiceInfo (
		[LineNo] INT,
		SerieCode NVARCHAR(50),
		StartingNo NVARCHAR(50),
		NextInvoice NVARCHAR(50),
		EndingNo NVARCHAR(50),
		Warning NVARCHAR(50),
		CAI NVARCHAR(100),
		FechaVenceRango DATE,
		RemainingInvoices int,
		RemainingDays int
	);

	INSERT INTO #TempInvoiceInfo
	EXEC [dbo].[EINextTicket] @GasStationCode ,
		@POSCode 

    DECLARE @LineNoNextInvoice INT;
	DECLARE @SerieCodeOfNextInvoice NVARCHAR(50);
    DECLARE @StartingNoOfNextInvoice NVARCHAR(50);
    DECLARE @NextInvoiceOfNextInvoice NVARCHAR(50); 
	DECLARE @EndingNoOfNextInvoice NVARCHAR(50);
	DECLARE @CAIOfNextInvoice NVARCHAR(100);
	DECLARE @FechaVenceRangoOfNextInvoice date; 
	DECLARE @RemainingInvoices int;
	DECLARE @RemainingDays int;


	
	SELECT TOP 1
		@LineNoNextInvoice = [LineNo],
		@SerieCodeOfNextInvoice = SerieCode,
		@StartingNoOfNextInvoice = StartingNo,
		@NextInvoiceOfNextInvoice = NextInvoice,
		@EndingNoOfNextInvoice = EndingNo,
		@CAIOfNextInvoice = CAI,
		@FechaVenceRangoOfNextInvoice = FechaVenceRango,
