	FROM #TempInvoiceInfo;
	
	DROP TABLE #TempInvoiceInfo;

	IF @RemainingInvoices IS NOT NULL AND @RemainingDays IS NOT NULL
	begin
	--//INICIO DE IF
		DECLARE @POSInvoiceNumberID NVARCHAR(50);
		SET @POSInvoiceNumberID = @NextInvoiceOfNextInvoice;
		-- Select @LineNoNextInvoice, @SerieCodeOfNextInvoice, @StartingNoOfNextInvoice, @NextInvoiceOfNextInvoice, @EndingNoOfNextInvoice
		--		@WarningOfNextInvoice, @WarningOfNextInvoice, @FechaVenceRangoOfNextInvoice
	
		--// Insertar los datos en la tabla [POS Sales Header]
		BEGIN TRY

    BEGIN TRANSACTION;

		INSERT INTO [POS Sales Header] (
			[POS Transaction ID],
			[Gas Station Code],
			[POS Code],
			[Inv_ Broadcaster No_],
			[POS Sales Doc_ Type],
			[POS Sales Doc_ No_],
			[Customer No_],
