			[Cust_ Name],
			[Cust_ Name 2],
			[Cust_ Address],
			[Cust_ Address 2],
			[Cust_ Post Code],
			[Cust_ City],
			[Cust_ County],
			[Cust_ Country_Reg_ Code],
			[Billing Type],
