			@CustAddress,
			@CustAddress2,
			@CustPostCode,
			@CustCity,
			@CustCounty,
			@CustCountryRegCode,
			@BillingType,
			@CustEmail,
			@Comment,
			@LineNoNextInvoice,
			@SubTotal
		);

    IF @@ROWCOUNT > 0
    BEGIN
		--//ACTUALIZANDO NUMERO TRANSACTION NUMBER
		update [No_ Series Line]
		set [Last No_ Used] = @NextPosTransactionIDNumber
		where [Series Code]= @SeriesCodeOfPosTransactionIDNumber AND [Line No_] = @LineNoOfPosTransactionIDNumber
	
		--//ACTUALIZANDO NUMERO FACTURA
		update [No_ Series Line]
		set [Last No_ Used] = @NextInvoiceOfNextInvoice
		where [Series Code]= @SerieCodeOfNextInvoice AND [Line No_] = @LineNoNextInvoice

		

INSERT INTO [dbo].[POS Transaction Log]
           ([POS Transaction ID]
           ,[Gas Station Code]
           ,[POS Code]
           ,[Shift Date]
           ,[Shift No_]
           ,[Transaction Type]
           ,[Transaction DateTime]
		   ,[EmployeeName]
           ,[Status])
     VALUES
           (
				@POSTransactionID,
				@GasStationCode,
				@POSCode,
				CONVERT(DATE, @FechaTurno),
				@Turno,
				7,
				GETDATE(),
				@EmployeeName,
				0
		   )


		SELECT @NextPosTransactionIDNumber AS NextPosTransactionIDNumber, @NextInvoiceOfNextInvoice AS NextInvoiceOfNextInvoice,
		@LineNoNextInvoice as LineNoNextInvoice ,
		@SerieCodeOfNextInvoice as SerieCodeOfNextInvoice,
