END TRY
BEGIN CATCH
    SELECT 'Actualizacion no realizada: ' + ERROR_MESSAGE();
    ROLLBACK TRANSACTION;
END CATCH;

		
			--//FIN DE IF
	end
END

create PROCEDURE [dbo].[EIInsertTicketFullV1]
    @GasStationCode NVARCHAR(50),
    @POSCode NVARCHAR(50),
    @InvBroadcasterNo NVARCHAR(50),
    -- @POSSalesDocType NO ES NECESARIO PEDIRLO, LO FORZAMOS A 7 (TICKET)
    @CustomerNo NVARCHAR(50),
    @Amount DECIMAL(38,20),
    @CustCardNo NVARCHAR(50),
    @PointsCardNo NVARCHAR(50),
    @PlateNo NVARCHAR(50),
    @RelSalesDocumentNo NVARCHAR(50),
    @SalespersonCode NVARCHAR(50),
    @VATRegNo NVARCHAR(50),
    @CustName NVARCHAR(100),
    @CustName2 NVARCHAR(100),
    @CustAddress NVARCHAR(100),
    @CustAddress2 NVARCHAR(100),
    @CustPostCode NVARCHAR(20),
    @CustCity NVARCHAR(50),
    @CustCounty NVARCHAR(50),
    @CustCountryRegCode NVARCHAR(50),
    @BillingType NVARCHAR(50),
    @CustEmail NVARCHAR(100),
    @Comment NVARCHAR(400),
    @FechaTurno DATETIME,
    @Turno NVARCHAR(2),
    @SubTotal DECIMAL(38,20),
    @Cambio DECIMAL(18,4),
    @EmployeeName NVARCHAR(20),
    @KM NVARCHAR(20),
    @Orden NVARCHAR(20),
    @Placa NVARCHAR(20),
    @Chofer NVARCHAR(20),
    @RangoIndividual INT,
    @Lines dbo.TVP_POSSalesLine READONLY,      -- Utiliza el tipo definido previamente
    @Payments dbo.TVP_POSPaymentMethod READONLY -- Utiliza el tipo definido previamente
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    -- Validaciones basicas
    IF NOT EXISTS (SELECT 1 FROM @Lines)
    BEGIN
        RAISERROR('Ticket inválido: no se recibieron líneas.', 16, 1);
        RETURN;
    END;

    IF NOT EXISTS (SELECT 1 FROM @Payments)
    BEGIN
        RAISERROR('Ticket inválido: no se recibieron pagos/cargos.', 16, 1);
        RETURN;
    END;

    DECLARE @SeriesCodeOfPosTransactionIDNumber NVARCHAR(50);
    DECLARE @LineNoOfPosTransactionIDNumber INT;
    DECLARE @NextPosTransactionIDNumber NVARCHAR(50);
    DECLARE @POSNumberFinal NVARCHAR(5) = '01';
    DECLARE @WarningNo INT;

    -- Logica de rango individual
    IF (@RangoIndividual = 1)
        SET @POSNumberFinal = @POSCode;

    -- Variables para el numero de Ticket
    DECLARE
        @LineNoNextInvoice INT,
        @SerieCodeOfNextInvoice NVARCHAR(50),
        @StartingNoOfNextInvoice NVARCHAR(50),
        @NextInvoiceOfNextInvoice NVARCHAR(50),
        @EndingNoOfNextInvoice NVARCHAR(50),
        @CAIOfNextInvoice NVARCHAR(100),
        @FechaVenceRangoOfNextInvoice DATE,
        @RemainingInvoices INT,
        @RemainingDays INT;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- 1. Obtener TR-ID (Transaction ID Global)
        EXEC dbo.EINextPosTransactionIDNumber
            @GasStationCode = @GasStationCode,
            @POSCode = @POSNumberFinal,
            @SeriesCode = @SeriesCodeOfPosTransactionIDNumber OUTPUT,
            @LineNo = @LineNoOfPosTransactionIDNumber OUTPUT,
            @NextPosTransactionIDNumber = @NextPosTransactionIDNumber OUTPUT;

        IF @NextPosTransactionIDNumber IS NULL
        BEGIN
            RAISERROR('No hay correlativo disponible para POS Transaction ID (TR-ID).', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END;

        DECLARE @POSTransactionID NVARCHAR(50) = @NextPosTransactionIDNumber;

        -- 2. Obtener Numero de Ticket (Usando EINextTicket en lugar de EINextInvoice)
        EXEC dbo.EINextTicket
            @GasStationCode = @GasStationCode,
            @POSCode = @POSNumberFinal,
            @LineNo = @LineNoNextInvoice OUTPUT,
            @SerieCode = @SerieCodeOfNextInvoice OUTPUT,
            @StartingNo = @StartingNoOfNextInvoice OUTPUT,
            @NextInvoice = @NextInvoiceOfNextInvoice OUTPUT,
            @EndingNo = @EndingNoOfNextInvoice OUTPUT,
            @CAI = @CAIOfNextInvoice OUTPUT,
            @FechaVenceRango = @FechaVenceRangoOfNextInvoice OUTPUT,
            @RemainingInvoices = @RemainingInvoices OUTPUT,
            @RemainingDays = @RemainingDays OUTPUT,
            @WarningNo = @WarningNo OUTPUT;

        -- Validar si se obtuvo numero de ticket
        IF @NextInvoiceOfNextInvoice IS NULL
        BEGIN
            RAISERROR('No hay correlativo disponible para TICKETS (Verifique tabla No_ Series Line para la serie TICKET).', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END;

        -- 3. Insertar Header (Tipo Ticket = 7)
        INSERT INTO [dbo].[POS Sales Header]
        (
            [POS Transaction ID],[Gas Station Code],[POS Code],[Inv_ Broadcaster No_],
            [POS Sales Doc_ Type],[POS Sales Doc_ No_],[Customer No_],[Sale Date Time],
            [Amount],[Cust_ Card No_],[Points Card No_],[Plate No_],[Rel_ Sales Document No_],
            [Salesperson Code],[VAT Reg_ No_],[Cust_ Name],[Cust_ Name 2],
            [Cust_ Address],[Cust_ Address 2],[Cust_ Post Code],[Cust_ City],
            [Cust_ County],[Cust_ Country_Reg_ Code],[Billing Type],[Cust_ E-Mail],
            [Comment],[Line No_],[SubTotal],[KM],[Orden],[Placa],[Chofer],[Cambio]
        )
        VALUES
        (
            @POSTransactionID,@GasStationCode,@POSCode,@InvBroadcasterNo,
            7, -- POS Sales Doc Type 7 = Ticket
            @NextInvoiceOfNextInvoice,@CustomerNo,GETDATE(),
            @Amount,@CustCardNo,@PointsCardNo,@PlateNo,@RelSalesDocumentNo,
            @SalespersonCode,@VATRegNo,@CustName,@CustName2,
            @CustAddress,@CustAddress2,@CustPostCode,@CustCity,
            @CustCounty,@CustCountryRegCode,
            CONVERT(INT, @BillingType), -- Se mantiene el billing type recibido
            @CustEmail,
            @Comment,@LineNoNextInvoice,@SubTotal,@KM,@Orden,@Placa,@Chofer,@Cambio
        );

        -- 4. Insertar Lines
        -- Nota: Quantity DECIMAL(38,20) en el TVP se mapea aqui. Asegurar que la DB soporte la precision deseada.
        INSERT INTO [dbo].[POS Sales Line]
        (
            [POS Transaction ID],[Gas Station Code],[POS Code],[Inv_ Broadcaster No_],
            [POS Sales Doc_ Type],[POS Sales Doc_ No_],[POS Sales Doc_ Line No_],
            [POS Sales Type],[POS Sales No_],[Description],[Quantity],
            [Unit Price Incl_ VAT],[Unit Discount Amount],[Discount _],[Line Discount Amount],
            [VAT _],[VAT_Amount],[Amount Including VAT],[Pump No_],[Pump Position No_],
            [Tank No_],[Operation Time],[Item Category Code],[Bonified],[Returned],
            [Gen_ Pump Ledg_ Entry],[VAT Prod_ Posting Group],[Source POS Transaction ID],
            [Source POS Sales Doc_ No_],[Source POS Sales Doc_ Line No_],[DOMS Trans No_],
            [Prepayment],[Return],[Applies-to Line No_],[Fidelity Points],[idFuelAttendant],[SaleID]
        )
        SELECT
            @POSTransactionID,@GasStationCode,@POSCode,@InvBroadcasterNo,
            7, -- Tipo Ticket
            @NextInvoiceOfNextInvoice,l.POSSalesDocLineNo,
            l.POSSalesType,l.POSSalesNo,l.[Description],l.Quantity,
            l.UnitPriceInclVAT,l.UnitDiscountAmount,l.Discount,l.LineDiscountAmount,
            l.VAT,l.VATAmount,l.AmountIncludingVAT,l.PumpNo,l.PumpPositionNo,
            l.TankNo,GETDATE(),l.ItemCategoryCode,l.Bonified,l.Returned,
            l.GenPumpLedgEntry,l.VATProdPostingGroup,l.SourcePOSTransactionID,
            l.SourcePOSSalesDocNo,l.SourcePOSSalesDocLineNo,l.DOMSTransNo,
            l.Prepayment,l.[Return],l.AppliesToLineNo,l.FidelityPoints,l.IdFuelAttendant,l.SaleID
        FROM @Lines l;

        -- 5. Insertar Payments
        INSERT INTO [dbo].[POS Sales Charge Line]
        (
            [POS Transaction ID],[Gas Station Code],[POS Code],[Charge Line No_],
            [Charge Method Code],[Amount],[MontoIngresado],[Payment Card No_],
            [Description],[Datos Adicionales],[idFuelAttendant],[TasaCambio],[EsTicket]
        )
        SELECT
            @POSTransactionID,@GasStationCode,@POSCode,
            p.ChargeLineNo,p.ChargeMethodCode,p.Amount,p.MontoIngresado,p.PaymentCardNo,
            p.[Description],p.AdditionalData,p.IdFuelAttendant,p.TasaCambio,p.EsTicket
        FROM @Payments p;

        -- 6. Actualizar Correlativo de TR-ID
        UPDATE [dbo].[No_ Series Line]
        SET [Last No_ Used] = @NextPosTransactionIDNumber, [Last Date Used] = GETDATE()
        WHERE [Series Code]= @SeriesCodeOfPosTransactionIDNumber AND [Line No_] = @LineNoOfPosTransactionIDNumber;

        -- 7. Actualizar Correlativo de Ticket
        UPDATE [dbo].[No_ Series Line]
        SET [Last No_ Used] = @NextInvoiceOfNextInvoice, [Last Date Used] = GETDATE()
        WHERE [Series Code]= @SerieCodeOfNextInvoice AND [Line No_] = @LineNoNextInvoice;

        -- 8. Insertar Log
        INSERT INTO [dbo].[POS Transaction Log]
        (
            [POS Transaction ID],[Gas Station Code],[POS Code],
            [Shift Date],[Shift No_],[Transaction Type],[Transaction DateTime],[EmployeeName],[Status]
        )
        VALUES
        (
            @POSTransactionID,@GasStationCode,@POSCode,
            CONVERT(DATE, @FechaTurno),@Turno,0,GETDATE(),@EmployeeName,0
        );

        COMMIT TRANSACTION;

        -- Retornar informacion clave tal como lo hace el SP de Facturas
        SELECT
            @NextPosTransactionIDNumber AS NextPosTransactionIDNumber,
            @NextInvoiceOfNextInvoice AS NextInvoiceOfNextInvoice,
            @LineNoNextInvoice AS LineNoNextInvoice,
            @SerieCodeOfNextInvoice AS SerieCodeOfNextInvoice,
            @StartingNoOfNextInvoice AS StartingNoOfNextInvoice,
            @EndingNoOfNextInvoice AS EndingNoOfNextInvoice,
            @CAIOfNextInvoice AS CAIOfNextInvoice,
            @FechaVenceRangoOfNextInvoice AS FechaVenceRangoOfNextInvoice,
            @RemainingInvoices AS RemainingInvoices,
            @RemainingDays AS RemainingDays,
            @WarningNo AS WarningNo;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR(@ErrorMessage, 16, 1);
    END CATCH
END

CREATE PROCEDURE [dbo].[EIInsertTicketV2]
    @GasStationCode NVARCHAR(50),
    @POSCode NVARCHAR(50),
    @InvBroadcasterNo NVARCHAR(50),
    @POSSalesDocType NVARCHAR(50),
    @CustomerNo NVARCHAR(50),
    @Amount DECIMAL(38, 20),
    @CustCardNo NVARCHAR(50),
    @PointsCardNo NVARCHAR(50),
    @PlateNo NVARCHAR(50),
    @RelSalesDocumentNo NVARCHAR(50),
    @SalespersonCode NVARCHAR(50),
    @VATRegNo NVARCHAR(50),
    @CustName NVARCHAR(100),
    @CustName2 NVARCHAR(100),
    @CustAddress NVARCHAR(100),
    @CustAddress2 NVARCHAR(100),
    @CustPostCode NVARCHAR(20),
    @CustCity NVARCHAR(50),
    @CustCounty NVARCHAR(50),
    @CustCountryRegCode NVARCHAR(50),
    @BillingType NVARCHAR(50),
    @CustEmail NVARCHAR(100),
    @Comment NVARCHAR(400),
    @FechaTurno DATETIME,
    @Turno NVARCHAR(2),
    @SubTotal DECIMAL(38, 20),
    @EmployeeName NVARCHAR(20),
    @RangoIndividual INT,
    @KM NVARCHAR(20) = NULL,
    @Orden NVARCHAR(20) = NULL,
    @Placa NVARCHAR(20) = NULL,
    @Chofer NVARCHAR(20) = NULL,
	@Cambio decimal(18,2) = '0.0'
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SeriesCodeOfPosTransactionIDNumber NVARCHAR(50),
            @LineNoOfPosTransactionIDNumber INT,
            @NextPosTransactionIDNumber NVARCHAR(50),
            @POSNumberFinal NVARCHAR(5) = '01',
            @WarningNo INT;

    IF (@RangoIndividual = 1)
        SET @POSNumberFinal = @POSCode;

    EXEC [dbo].[EINextPosTransactionIDNumber]
        @GasStationCode = @GasStationCode,
        @POSCode = @POSNumberFinal,
        @SeriesCode = @SeriesCodeOfPosTransactionIDNumber OUTPUT,
        @LineNo = @LineNoOfPosTransactionIDNumber OUTPUT,
        @NextPosTransactionIDNumber = @NextPosTransactionIDNumber OUTPUT;

    DECLARE @POSTransactionID NVARCHAR(50) = @NextPosTransactionIDNumber;

    DECLARE @LineNoNextInvoice INT,
            @SerieCodeOfNextInvoice NVARCHAR(50),
            @StartingNoOfNextInvoice NVARCHAR(50),
            @NextInvoiceOfNextInvoice NVARCHAR(50),
            @EndingNoOfNextInvoice NVARCHAR(50),
            @CAIOfNextInvoice NVARCHAR(100),
            @FechaVenceRangoOfNextInvoice DATE,
            @RemainingInvoices INT,
            @RemainingDays INT;

    EXEC [dbo].[EINextTicket]
        @GasStationCode = @GasStationCode,
        @POSCode = @POSNumberFinal,
        @LineNo = @LineNoNextInvoice OUTPUT,
        @SerieCode = @SerieCodeOfNextInvoice OUTPUT,
        @StartingNo = @StartingNoOfNextInvoice OUTPUT,
        @NextInvoice = @NextInvoiceOfNextInvoice OUTPUT,
        @EndingNo = @EndingNoOfNextInvoice OUTPUT,
        @CAI = @CAIOfNextInvoice OUTPUT,
        @FechaVenceRango = @FechaVenceRangoOfNextInvoice OUTPUT,
        @RemainingInvoices = @RemainingInvoices OUTPUT,
        @RemainingDays = @RemainingDays OUTPUT,
        @WarningNo = @WarningNo OUTPUT;

    IF @RemainingInvoices IS NOT NULL AND @RemainingDays IS NOT NULL
    BEGIN
        BEGIN TRY
            BEGIN TRANSACTION;

            INSERT INTO [POS Sales Header] (
                [POS Transaction ID], [Gas Station Code], [POS Code], [Inv_ Broadcaster No_],
                [POS Sales Doc_ Type], [POS Sales Doc_ No_], [Customer No_], [Sale Date Time],
                [Amount], [Cust_ Card No_], [Points Card No_], [Plate No_], [Rel_ Sales Document No_],
                [Salesperson Code], [VAT Reg_ No_], [Cust_ Name], [Cust_ Name 2], [Cust_ Address],
                [Cust_ Address 2], [Cust_ Post Code], [Cust_ City], [Cust_ County], [Cust_ Country_Reg_ Code],
                [Billing Type], [Cust_ E-Mail], [Comment], [Line No_], [SubTotal],
                [KM], [Orden], [Placa], [Chofer],[Cambio]
            )
            VALUES (
                @POSTransactionID, @GasStationCode, @POSCode, @InvBroadcasterNo,
                @POSSalesDocType, @NextInvoiceOfNextInvoice, @CustomerNo, GETDATE(),
                @Amount, @CustCardNo, @PointsCardNo, @PlateNo, @RelSalesDocumentNo,
                @SalespersonCode, @VATRegNo, @CustName, @CustName2, @CustAddress,
                @CustAddress2, @CustPostCode, @CustCity, @CustCounty, @CustCountryRegCode,
                @BillingType, @CustEmail, @Comment, @LineNoNextInvoice, @SubTotal,
                @KM, @Orden, @Placa, @Chofer, @Cambio
            );

            UPDATE [No_ Series Line]
            SET [Last No_ Used] = @NextPosTransactionIDNumber, [Last Date Used] = GETDATE()
            WHERE [Series Code]= @SeriesCodeOfPosTransactionIDNumber AND [Line No_] = @LineNoOfPosTransactionIDNumber;

            UPDATE [No_ Series Line]
            SET [Last No_ Used] = @NextInvoiceOfNextInvoice, [Last Date Used] = GETDATE()
            WHERE [Series Code]= @SerieCodeOfNextInvoice AND [Line No_] = @LineNoNextInvoice;

            INSERT INTO [dbo].[POS Transaction Log] (
                [POS Transaction ID], [Gas Station Code], [POS Code],
                [Shift Date], [Shift No_], [Transaction Type],
                [Transaction DateTime], [EmployeeName], [Status]
            )
            VALUES (
                @POSTransactionID, @GasStationCode, @POSCode,
                CONVERT(DATE, @FechaTurno), @Turno, 7,
                GETDATE(), @EmployeeName, 0
            );

            SELECT 
                @NextPosTransactionIDNumber AS NextPosTransactionIDNumber,
                @NextInvoiceOfNextInvoice AS NextInvoiceOfNextInvoice,
                @LineNoNextInvoice AS LineNoNextInvoice,
                @SerieCodeOfNextInvoice AS SerieCodeOfNextInvoice,
                @StartingNoOfNextInvoice AS StartingNoOfNextInvoice,
                @EndingNoOfNextInvoice AS EndingNoOfNextInvoice,
                @CAIOfNextInvoice AS CAIOfNextInvoice,
                @FechaVenceRangoOfNextInvoice AS FechaVenceRangoOfNextInvoice,
                @RemainingInvoices AS RemainingInvoices,
                @RemainingDays AS RemainingDays,
                @WarningNo AS WarningNo;

            COMMIT;
        END TRY
        BEGIN CATCH
            ROLLBACK;
            SELECT 'Actualizacion no realizada: ' + ERROR_MESSAGE() AS ErrorMessage;
        END CATCH;
    END
END

CREATE PROCEDURE [dbo].[EINextCreditNote]
    @GasStationCode VARCHAR(10),
    @POSCode VARCHAR(10),
    @LineNo INT OUTPUT,
    @SerieCode NVARCHAR(50) OUTPUT,
    @StartingNo NVARCHAR(50) OUTPUT,
    @NextInvoice NVARCHAR(50) OUTPUT,
    @EndingNo NVARCHAR(50) OUTPUT,
    @CAI NVARCHAR(100) OUTPUT,
    @FechaVenceRango DATE OUTPUT,
    @RemainingInvoices INT OUTPUT,
    @RemainingDays INT OUTPUT,
    @WarningNo INT OUTPUT
AS
BEGIN
    SELECT TOP (1)
        @LineNo = [Line No_],
        @SerieCode = [Series Code],
        @StartingNo = [Starting No_],
        @NextInvoice = CONCAT(SUBSTRING([Last No_ Used], 1, 11), RIGHT('00000000' + CAST(CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT) + 1 AS VARCHAR(8)), 8)),
        @EndingNo = [Ending No_],
        @WarningNo = [Warning No_],
        @CAI = [CAI],
        @FechaVenceRango = [Fecha Vence Rango],
        @RemainingInvoices = (CAST(SUBSTRING([Ending No_], 12, 19) AS INT) - CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT)),
        @RemainingDays = DATEDIFF(DAY, CONVERT(DATE, GETDATE()), CONVERT(DATE, [Fecha Vence Rango]))
    FROM [dbo].[No_ Series Line]
    WHERE 
        CONVERT(DATE, [Fecha Vence Rango]) >= CONVERT(DATE, GETDATE()) 
        AND CONVERT(DATE, [Starting Date]) <= CONVERT(DATE, GETDATE()) 
        AND [Series Code] = 'NC-HN'
        AND [Open] = 1
        AND RIGHT('00000000' + CAST(CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT) + 1 AS VARCHAR(8)), 8) >= SUBSTRING([Starting No_], 12, 19)
        AND RIGHT('00000000' + CAST(CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT) + 1 AS VARCHAR(8)), 8) <= SUBSTRING([Ending No_], 12, 19) 
        AND [Gas Station Code] = @GasStationCode
        AND [POS Code] = @POSCode
    ORDER BY [Line No_] ASC
END

