CREATE PROCEDURE [dbo].[EINextInvoice]
    @GasStationCode VARCHAR(10),
    @POSCode VARCHAR(10),
    @LineNo INT OUTPUT,
    @SerieCode NVARCHAR(50) OUTPUT,
    @StartingNo NVARCHAR(50) OUTPUT,
    @NextInvoice NVARCHAR(50) OUTPUT,
    @EndingNo NVARCHAR(50) OUTPUT,
    @CAI NVARCHAR(100) OUTPUT,
    @FechaVenceRango DATE OUTPUT,
    @RemainingInvoices INT OUTPUT,
    @RemainingDays INT OUTPUT,
    @WarningNo int OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @tmpLineNo INT,
            @tmpSerieCode NVARCHAR(50),
            @tmpStartingNo NVARCHAR(50),
            @tmpNextInvoice NVARCHAR(50),
            @tmpEndingNo NVARCHAR(50),
            @tmpCAI NVARCHAR(100),
            @tmpFechaVenceRango DATE,
            @tmpRemainingInvoices INT,
            @tmpRemainingDays INT,
            @tmpWarningNo INT;

    SELECT TOP (1)
        @tmpLineNo = [Line No_],
        @tmpSerieCode = [Series Code],
        @tmpStartingNo = [Starting No_],
        @tmpNextInvoice = CONCAT(
            SUBSTRING([Last No_ Used], 1, 11),
            RIGHT('00000000' + CAST(CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT) + 1 AS VARCHAR(8)), 8)
        ),
        @tmpEndingNo = [Ending No_],
        @tmpCAI = [CAI],
        @tmpFechaVenceRango = [Fecha Vence Rango],
        @tmpRemainingInvoices = CAST(SUBSTRING([Ending No_], 12, 19) AS INT) - CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT),
        @tmpRemainingDays = DATEDIFF(DAY, CONVERT(DATE, GETDATE()), CONVERT(DATE, [Fecha Vence Rango])),
        @tmpWarningNo = [Warning No_]
    FROM [dbo].[No_ Series Line] WITH (UPDLOCK, HOLDLOCK)
    WHERE
        CONVERT(DATE, [Fecha Vence Rango]) >= CONVERT(DATE, GETDATE())
        AND CONVERT(DATE, [Starting Date]) <= CONVERT(DATE, GETDATE())
        AND [Series Code] = 'FV-HN'
        AND [Open] = 1
        AND RIGHT('00000000' + CAST(CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT) + 1 AS VARCHAR(8)), 8) >= SUBSTRING([Starting No_], 12, 19)
