        AND [Gas Station Code] = @GasStationCode
        AND [POS Code] = @POSCode
    ORDER BY [Line No_] ASC;

    SET @LineNo = @tmpLineNo;
    SET @SerieCode = @tmpSerieCode;
    SET @StartingNo = @tmpStartingNo;
    SET @NextInvoice = @tmpNextInvoice;
    SET @EndingNo = @tmpEndingNo;
    SET @CAI = @tmpCAI;
    SET @FechaVenceRango = @tmpFechaVenceRango;
    SET @RemainingInvoices = @tmpRemainingInvoices;
    SET @RemainingDays = @tmpRemainingDays;
    SET @WarningNo = @tmpWarningNo;
END

