    @LineNo INT OUTPUT,
    @SerieCode NVARCHAR(50) OUTPUT,
    @StartingNo NVARCHAR(50) OUTPUT,
    @NextInvoice NVARCHAR(50) OUTPUT,
    @EndingNo NVARCHAR(50) OUTPUT,
    @CAI NVARCHAR(100) OUTPUT,
    @FechaVenceRango DATE OUTPUT,
    @RemainingInvoices INT OUTPUT,
    @RemainingDays INT OUTPUT,
	@WarningNo int OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @tmpLineNo INT,
            @tmpSerieCode NVARCHAR(50),
            @tmpStartingNo NVARCHAR(50),
            @tmpNextInvoice NVARCHAR(50),
            @tmpEndingNo NVARCHAR(50),
            @tmpCAI NVARCHAR(100),
            @tmpFechaVenceRango DATE,
            @tmpRemainingInvoices INT,
            @tmpRemainingDays INT,
			@tmpWarningNo INT;

    SELECT TOP (1)
        @tmpLineNo = [Line No_],
        @tmpSerieCode = [Series Code],
        @tmpStartingNo = [Starting No_],
        @tmpNextInvoice = CONCAT(
            SUBSTRING([Last No_ Used], 1, 11), 
            RIGHT('00000000' + CAST(CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT) + 1 AS VARCHAR(8)), 8)
        ),
        @tmpEndingNo = [Ending No_],
        @tmpCAI = [CAI],
        @tmpFechaVenceRango = [Fecha Vence Rango],
        @tmpRemainingInvoices = CAST(SUBSTRING([Ending No_], 12, 19) AS INT) - CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT),
        @tmpRemainingDays = DATEDIFF(DAY, CONVERT(DATE, GETDATE()), CONVERT(DATE, [Fecha Vence Rango])),
		@tmpWarningNo = [Warning No_]
    FROM [dbo].[No_ Series Line]
    WHERE 
        CONVERT(DATE, [Fecha Vence Rango]) >= CONVERT(DATE, GETDATE()) 
        AND CONVERT(DATE, [Starting Date]) <= CONVERT(DATE, GETDATE()) 
        AND [Series Code] = 'FV-HN'
        AND [Open] = 1
        AND RIGHT('00000000' + CAST(CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT) + 1 AS VARCHAR(8)), 8) >= SUBSTRING([Starting No_], 12, 19)
        AND RIGHT('00000000' + CAST(CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT) + 1 AS VARCHAR(8)), 8) <= SUBSTRING([Ending No_], 12, 19)
        AND [Gas Station Code] = @GasStationCode
        AND [POS Code] = @POSCode
    ORDER BY [Line No_] ASC;

    -- ASIGNAR OUTPUTS
    SET @LineNo = @tmpLineNo;
    SET @SerieCode = @tmpSerieCode;
    SET @StartingNo = @tmpStartingNo;
    SET @NextInvoice = @tmpNextInvoice;
    SET @EndingNo = @tmpEndingNo;
    SET @CAI = @tmpCAI;
    SET @FechaVenceRango = @tmpFechaVenceRango;
    SET @RemainingInvoices = @tmpRemainingInvoices;
    SET @RemainingDays = @tmpRemainingDays;
	SET @WarningNo = @tmpWarningNo;
END

CREATE PROCEDURE [dbo].[EINextPosTransactionIDNumber]
    @GasStationCode VARCHAR(10),
    @POSCode VARCHAR(10),
    @SeriesCode NVARCHAR(50) OUTPUT,
    @LineNo INT OUTPUT,
    @NextPosTransactionIDNumber NVARCHAR(50) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @LastNoUsed NVARCHAR(50);

    SELECT TOP (1)
        @SeriesCode = [Series Code],
        @LineNo = [Line No_],
        @LastNoUsed = [Last No_ Used]
    FROM [dbo].[No_ Series Line] WITH (UPDLOCK, HOLDLOCK)
    WHERE
        CONVERT(DATE, [Fecha Vence Rango]) >= CONVERT(DATE, GETDATE())
        AND CONVERT(DATE, [Starting Date]) <= CONVERT(DATE, GETDATE())
        AND [Series Code] = 'TR-ID'
        AND [Open] = 1
        AND [Gas Station Code] = @GasStationCode
        AND [POS Code] = @POSCode
    ORDER BY [Line No_] ASC;

    IF @LastNoUsed IS NOT NULL
    BEGIN
        SET @NextPosTransactionIDNumber =
            CONCAT(
                SUBSTRING(@LastNoUsed, 1, 6),
                RIGHT('00000000000' + CAST(CAST(SUBSTRING(@LastNoUsed, 7, 11) AS BIGINT) + 1 AS VARCHAR(11)), 11)
            );
    END
END

CREATE PROCEDURE [dbo].[EINextTicket]
    @GasStationCode VARCHAR(10),
    @POSCode VARCHAR(10),
    @LineNo INT OUTPUT,
    @SerieCode NVARCHAR(50) OUTPUT,
    @StartingNo NVARCHAR(50) OUTPUT,
    @NextInvoice NVARCHAR(50) OUTPUT,
    @EndingNo NVARCHAR(50) OUTPUT,
    @CAI NVARCHAR(100) OUTPUT, -- Se puede dejar vacio o NULL si no aplica
    @FechaVenceRango DATE OUTPUT, -- Se puede dejar NULL si no aplica
    @RemainingInvoices INT OUTPUT, -- Informativo
    @RemainingDays INT OUTPUT, -- Informativo
    @WarningNo int OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @tmpLineNo INT,
            @tmpSerieCode NVARCHAR(50),
            @tmpStartingNo NVARCHAR(50),
            @tmpNextInvoice NVARCHAR(50),
            @tmpEndingNo NVARCHAR(50),
            @tmpCAI NVARCHAR(100),
            @tmpFechaVenceRango DATE,
            @tmpRemainingInvoices INT,
            @tmpRemainingDays INT,
            @tmpWarningNo INT;

    -- BUSCAR LA SERIE DEL TICKET
    -- AJUSTAR 'TICKET' SI EL CODIGO EN SU BASE DE DATOS ES DIFERENTE
    SELECT TOP (1)
        @tmpLineNo = [Line No_],
        @tmpSerieCode = [Series Code],
        @tmpStartingNo = [Starting No_],
        @tmpNextInvoice = CONCAT(
            SUBSTRING([Last No_ Used], 1, 11),
            RIGHT('00000000' + CAST(CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT) + 1 AS VARCHAR(8)), 8)
        ),
        @tmpEndingNo = [Ending No_],
        @tmpCAI = [CAI],
        @tmpFechaVenceRango = [Fecha Vence Rango],
        @tmpRemainingInvoices = CAST(SUBSTRING([Ending No_], 12, 19) AS INT) - CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT),
        -- Para tickets quizas no aplique vencimiento, pero mantenemos la logica por consistencia o ponemos dummy values
        @tmpRemainingDays = DATEDIFF(DAY, CONVERT(DATE, GETDATE()), CONVERT(DATE, [Fecha Vence Rango])),
        @tmpWarningNo = [Warning No_]
    FROM [dbo].[No_ Series Line] WITH (UPDLOCK, HOLDLOCK)
    WHERE
        [Series Code] = 'TK-HN' -- <--- VERIFICAR ESTE CODIGO DE SERIE EN SU DB
        AND [Open] = 1
        -- Validaciones de rango y fechas si aplican, sino simplificar
        AND CONVERT(DATE, [Fecha Vence Rango]) >= CONVERT(DATE, GETDATE()) 
        AND CONVERT(DATE, [Starting Date]) <= CONVERT(DATE, GETDATE())
        AND RIGHT('00000000' + CAST(CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT) + 1 AS VARCHAR(8)), 8) >= SUBSTRING([Starting No_], 12, 19)
        AND RIGHT('00000000' + CAST(CAST(SUBSTRING([Last No_ Used], 12, 19) AS INT) + 1 AS VARCHAR(8)), 8) <= SUBSTRING([Ending No_], 12, 19)
        AND [Gas Station Code] = @GasStationCode
        AND [POS Code] = @POSCode
    ORDER BY [Line No_] ASC;

    -- Si no se encontro serie valida
    IF @tmpNextInvoice IS NULL
    BEGIN
         -- Logica fallback o error si es estricto. Por ahora retornamos NULLs
         SET @NextInvoice = NULL;
         RETURN;
    END

    SET @LineNo = @tmpLineNo;
    SET @SerieCode = @tmpSerieCode;
    SET @StartingNo = @tmpStartingNo;
    SET @NextInvoice = @tmpNextInvoice;
    SET @EndingNo = @tmpEndingNo;
    SET @CAI = @tmpCAI;
    SET @FechaVenceRango = @tmpFechaVenceRango;
    SET @RemainingInvoices = @tmpRemainingInvoices;
    SET @RemainingDays = @tmpRemainingDays;
    SET @WarningNo = @tmpWarningNo;
END

CREATE PROCEDURE [dbo].[GetBomberoInfo]
    @GasStation NVARCHAR(10),
    @PosCode NVARCHAR(10),
    @FechaTurno DATE,
    @Turno INT,
    @idFuelAttendant INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Result VARCHAR(MAX);
    DECLARE @FuelAttendantName NVARCHAR(100);

    -- Obtener el nombre del despachador una sola vez
    SELECT @FuelAttendantName = CONCAT(FA.Nombres, ' ', FA.Apellidos)
    FROM FuelAttendant FA
    WHERE FA.idFuelAttendant = @idFuelAttendant;

    -- Concatenar los números de las bombas
    SELECT @Result = STUFF((
        SELECT DISTINCT ' | ' + PSL2.[Pump No_]
        FROM [TPV].[dbo].[POS Sales Line] PSL2
        LEFT JOIN [POS Transaction Log] PTL2 ON PSL2.[POS Transaction ID] = PTL2.[POS Transaction ID]
        WHERE 
            PSL2.[Gas Station Code] = @GasStation 
            AND PSL2.[POS Code] = @PosCode 
            AND PTL2.[Shift Date] = @FechaTurno 
            AND PTL2.[Shift No_] = @Turno
            AND PSL2.[idFuelAttendant] = @idFuelAttendant
        FOR XML PATH(''), TYPE).value('.', 'VARCHAR(MAX)'), 1, 3, '');

    -- Devolver el resultado final con el nombre y las bombas concatenadas
    SELECT CONCAT(@FuelAttendantName, ' | ', @Result) AS Bombero;
END

