CREATE PROCEDURE [dbo].[GetMaxDocument]
    @tipoSerie NVARCHAR(10),
    @estacion  VARCHAR(10)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @siguiente INT;

    SELECT 
        @siguiente = MAX([Line No_]) + 1
    FROM [TPV].[dbo].[No_ Series Line]
    WHERE [Series Code] = @tipoSerie
      AND [Gas Station Code] = @estacion;

    -- Si no hay registros
    IF @siguiente IS NULL
    BEGIN
        SET @siguiente = 
            CASE @tipoSerie
                WHEN 'FV-HN' THEN 10000
                WHEN 'NC-HN' THEN 40000
                WHEN 'TK-HN' THEN 30000
                WHEN 'TR-ID' THEN 21000
                ELSE 1
            END;
    END

    SELECT @siguiente AS NextDocument;
END;

CREATE PROCEDURE [dbo].[GetNextShift]
    @numeroPos NVARCHAR(5),
    @StoreID NVARCHAR(5)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @PosCode VARCHAR(50);
    DECLARE @CurrentShiftDate DATE;
    DECLARE @CurrentShiftNumber INT;
    DECLARE @POSTransactionID VARCHAR(50);
    DECLARE @turnosPermitivos INT;

    DECLARE @NextShiftDate DATE;
    DECLARE @NextShiftNumber INT;

    -- Obteniendo el número de turnos permitidos para la tienda
    SELECT TOP 1 @turnosPermitivos = Turnos FROM [Store] WHERE [StoreID] = @StoreID;

    -- Obteniendo la información del último turno del punto de venta y la tienda
    SELECT TOP 1 
        @PosCode = [PosCode],
        @CurrentShiftDate = [ShiftDate],
        @CurrentShiftNumber = [ShiftNumber],
        @POSTransactionID = [POS Transaction ID]
    FROM 
        [StoreLines]
    WHERE 
        PosCode = @numeroPos AND StoreID = @StoreID;

    -- Definiendo el nuevo turno
    IF @CurrentShiftNumber < @turnosPermitivos
    BEGIN
        SET @NextShiftNumber = @CurrentShiftNumber + 1;
        SET @NextShiftDate = @CurrentShiftDate;
    END
    ELSE IF @CurrentShiftNumber = @turnosPermitivos
    BEGIN
        SET @NextShiftNumber = 1;
        SET @NextShiftDate = DATEADD(DAY, 1, @CurrentShiftDate);
    END

    -- Retornando el número y fecha del próximo turno
    SELECT @NextShiftNumber AS NextShiftNumber, @NextShiftDate AS NextShiftDate;
END

