CREATE PROCEDURE [dbo].[GetTotalEfectivo-MovCaja]
    @TURNO INT,
    @Fechaturno DATE,
    @StoreID NVARCHAR(50),
    @PosCode NVARCHAR(50),
	@EmployeeName NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @TotalCashEntries DECIMAL(18, 2);
    DECLARE @TotalSalesCharge DECIMAL(18, 2);
    DECLARE @Result DECIMAL(18, 2);

    -- Obtener el total de la primera consulta
    SELECT 
        @TotalCashEntries = COALESCE(SUM(PCE.[Amount]), 0)
    FROM [dbo].[POS Cash Entries] PCE
    LEFT JOIN [POS Transaction Log] PTL 
        ON PCE.[POS Transaction ID] = PTL.[POS Transaction ID]
    WHERE PTL.[Shift No_] = @TURNO
          AND CONVERT(date, PTL.[Shift Date]) = @Fechaturno
          AND PTL.[Gas Station Code] = @StoreID
		  AND PTL.EmployeeName= @EmployeeName  
          AND 1=1 /* AND 1=1 /* AND PTL.[POS Code] = @PosCode */ */;

    -- Obtener el total de la segunda consulta
    SELECT 
        @TotalSalesCharge = COALESCE(SUM(PSCL.[Amount]), 0)
    FROM [dbo].[POS Sales Charge Line] PSCL
    LEFT JOIN [POS Transaction Log] PTL 
        ON PSCL.[POS Transaction ID] = PTL.[POS Transaction ID]
    WHERE PTL.[Shift No_] = @TURNO
          AND CONVERT(date, PTL.[Shift Date]) = @Fechaturno
          AND PTL.[Gas Station Code] = @StoreID
		  AND PTL.EmployeeName= @EmployeeName  
          AND 1=1 /* AND 1=1 /* AND PTL.[POS Code] = @PosCode */ */
          AND PSCL.[Charge Method Code] = '1001';

    -- Calcular la diferencia
    SET @Result =  @TotalSalesCharge -  @TotalCashEntries;

    -- Devolver el resultado
    SELECT @Result AS TotalDifference;
END;

