CREATE PROCEDURE [dbo].[GetUniquePumpNumbersWithEmployee]
    @Fechaturno DATE,
    @StoreID NVARCHAR(5),
    @PosCode NVARCHAR(5),
    @EmployeeName NVARCHAR(50),
    @TURNO INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT DISTINCT 
        PSL.[Pump No_] as Dispensador,
        PTL.[EmployeeName] as Nombre
    FROM [TPV].[dbo].[POS Transaction Log] PTL
    LEFT JOIN [TPV].[dbo].[POS Sales Line] PSL 
