        AND PSL.[Gas Station Code] = @StoreID
        -- AND PSL.[POS Code] = @PosCode -- Eliminado para soporte global
		AND CONVERT(date,  PTL.[Shift Date]) = @Fechaturno
        AND PTL.[EmployeeName] = @EmployeeName;
END;

CREATE PROCEDURE [dbo].[Insertar_SalesPrice_Item]
    -- Parámetros para la tabla Item
    @No NVARCHAR(20),
    @Description NVARCHAR(100),
    @ItemUnitPrice DECIMAL(18,2),
    @Blocked TINYINT,
    @Picture IMAGE = NULL,
    @VAT_Prod_Posting_Group NVARCHAR(20),
    @Item_Category_Code NVARCHAR(20),
    @Product_Group_Code NVARCHAR(10),
    @Bonified TINYINT,
    @UoM_Conversion_Factor DECIMAL(18,2),
    @Labels_UoM_Code NVARCHAR(10),
    @Gen_Pump_Ledg_Entry TINYINT,
    @Item_Disc_Group NVARCHAR(20) = '',
    @POS_Price_Change_Allowed TINYINT = 0,
    @PROM_Item_Category_Code NVARCHAR(20) = '',
    @POS_Negative_Quantity_Allowed TINYINT = 0,
    @BC_ID NVARCHAR(40) = NULL,
    @VendorId INT = NULL,
    @IsAgeDiscountApplied BIT = NULL,

    -- Parámetros para la tabla Sales Price
    @ItemNo NVARCHAR(20),
    @Gas_Station_Code NVARCHAR(10),
    @Minimum_Quantity DECIMAL(18,2),
    @Unit_Price DECIMAL(18,2),
    @Status TINYINT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        -- Insertar en la tabla Item
        INSERT INTO [dbo].[Item] (
            [No_], [Description], [Unit Price], [Blocked], [Picture], 
            [VAT Prod_ Posting Group], [Item Category Code], [Product Group Code], 
            [Bonified], [UoM Conversion Factor], [Labels UoM Code], 
            [Gen_ Pump Ledg_ Entry], [Item Disc_ Group], [POS Price Change Allowed], 
            [PROM Item Category Code], [POS Negative Quantity Allowed], 
            [BC_ID], [vendorId], [IsAgeDiscountApplied]
        ) 
        VALUES (
            @No, @Description, @ItemUnitPrice, @Blocked, @Picture, 
            @VAT_Prod_Posting_Group, @Item_Category_Code, @Product_Group_Code, 
            @Bonified, @UoM_Conversion_Factor, @Labels_UoM_Code, 
            @Gen_Pump_Ledg_Entry, @Item_Disc_Group, @POS_Price_Change_Allowed, 
            @PROM_Item_Category_Code, @POS_Negative_Quantity_Allowed, 
            @BC_ID, @VendorId, @IsAgeDiscountApplied
        );

        -- Insertar en la tabla Sales Price
        INSERT INTO [dbo].[Sales Price] (
            [Item No_], [Gas Station Code], [Starting Date], [Starting Time], 
            [Minimum Quantity], [Unit Price], [Ending Date], [Ending Time], [Status],[Id]
        ) 
        VALUES (
            @ItemNo, @Gas_Station_Code, GETDATE(), '1900-01-01 00:00:00.857', 
            @Minimum_Quantity, @Unit_Price, '2100-01-01 00:00:00.857', '2100-01-01 00:00:00.857', @Status, 0
        );

        -- Confirmar transacción
        COMMIT TRANSACTION;

        -- Devolver los datos insertados
        SELECT 'Éxito' AS Resultado, 'Datos insertados correctamente' AS Mensaje;
    END TRY
    BEGIN CATCH
        -- Si hay error, hacer rollback
        ROLLBACK TRANSACTION;

        -- Devolver mensaje de error
        SELECT 'Error' AS Resultado, ERROR_MESSAGE() AS Mensaje;
    END CATCH
END;

