CREATE PROCEDURE [dbo].[InsertPaymentMethods]
    @POSTransactionID NVARCHAR(40),
    @GasStationCode NVARCHAR(20),
    @POSCode NVARCHAR(20),
    @ChargeLineNo INT,
    @ChargeMethodCode NVARCHAR(20),
    @Amount DECIMAL(17, 2),
	@MontoIngresado decimal(18,2),
    @PaymentCardNo NVARCHAR(40),
    @Description NVARCHAR(100),
    @AdditionalData NVARCHAR(max),
	@IdFuelAttendant int,
	@TasaCambio DECIMAL(18, 2),
	@EsTicket int,
    @Success INT OUTPUT
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO [POS Sales Charge Line] (
            [POS Transaction ID],
            [Gas Station Code],
            [POS Code],
            [Charge Line No_],
            [Charge Method Code],
            [Amount],
			[MontoIngresado],
            [Payment Card No_],
            [Description],
            [Datos Adicionales],
			[idFuelAttendant],
			[TasaCambio],
			[EsTicket]
        )
        VALUES (
            @POSTransactionID,
            @GasStationCode,
            @POSCode,
            @ChargeLineNo,
            @ChargeMethodCode,
            @Amount,
			@MontoIngresado,
            @PaymentCardNo,
            @Description,
            @AdditionalData,
			@IdFuelAttendant,
			@TasaCambio,
			@EsTicket
        );

        -- Indicar éxito
        SET @Success = 1;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
        BEGIN
            ROLLBACK TRANSACTION;
        END

        -- Indicar error
        SET @Success = 0;

        -- Lanzar error para capturar detalles
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR(@ErrorMessage, 16, 1);
    END CATCH;
END;

