CREATE PROCEDURE [dbo].[NextShift]
    @IdWeekDay INT,
    @numeroPos NVARCHAR(5),
    @StoreID NVARCHAR(5),
    @CurrentDate DATE,
    @idWeekDayOut INT OUTPUT,
    @weekDayOut NVARCHAR(20) OUTPUT,
    @shiftNameOut NVARCHAR(50) OUTPUT,
    @levelOut INT OUTPUT,
    @ShiftDateOut DATE OUTPUT,
    @StatusCode INT OUTPUT,  -- Código de estado para indicar éxito o error
    @ErrorMessage NVARCHAR(255) OUTPUT  -- Mensaje de error en caso de fallo
AS
BEGIN
    BEGIN TRY
        -- Inicializar variables de salida
        SET @idWeekDayOut = NULL;
        SET @weekDayOut = NULL;
        SET @shiftNameOut = NULL;
        SET @levelOut = NULL;
        SET @ShiftDateOut = NULL;
        SET @StatusCode = 0;
        SET @ErrorMessage = NULL;

        DECLARE @CurrentLevel INT;
        DECLARE @NextLevel INT = 0;
        DECLARE @CurrentDay NVARCHAR(20);
        DECLARE @SystemDay NVARCHAR(20) = UPPER(FORMAT(GETDATE(), 'dddd', 'es-ES'));
        DECLARE @SystemDate DATE = CONVERT(DATE, GETDATE());

        -- Validar existencia de configuración para el turno actual
        IF NOT EXISTS (
            SELECT 1
            FROM [StoreShiftConfiguration]
            WHERE idWeekDay = @IdWeekDay AND [idStore] = @StoreID AND [posCode] = @numeroPos
        )
        BEGIN
            SET @StatusCode = -1;
            SET @ErrorMessage = 'No se encontró configuración para el turno actual.';
            RETURN;
        END;

        -- Obtener el nivel actual del turno
        SELECT @CurrentLevel = [level],
               @CurrentDay = [weekDay]
        FROM [StoreShiftConfiguration]
        WHERE idWeekDay = @IdWeekDay AND [idStore] = @StoreID AND [posCode] = @numeroPos;

        IF @CurrentLevel IS NULL OR @CurrentDay IS NULL
        BEGIN
            SET @StatusCode = -4;
            SET @ErrorMessage = 'Datos incompletos para el turno actual.';
            RETURN;
        END;

        -- Determinar el siguiente nivel
        IF @CurrentDay = @SystemDay AND @CurrentDate = @SystemDate
        BEGIN
            SELECT TOP 1 @NextLevel = level
            FROM [StoreShiftConfiguration]
            WHERE level > @CurrentLevel AND [idStore] = @StoreID AND [posCode] = @numeroPos AND isActive = 1
            ORDER BY level ASC;

            IF @NextLevel IS NULL
            BEGIN
                SELECT TOP 1 @NextLevel = level
                FROM [StoreShiftConfiguration]
                WHERE level = 1 AND [idStore] = @StoreID AND [posCode] = @numeroPos AND isActive = 1
                ORDER BY level ASC;
            END;
        END
        ELSE
        BEGIN
            SELECT TOP 1 @NextLevel = MIN(level)
            FROM [StoreShiftConfiguration]
            WHERE weekDay = @SystemDay AND [idStore] = @StoreID AND [posCode] = @numeroPos AND isActive = 1;
        END;

        -- Validar si se encontró un nivel
        IF @NextLevel IS NULL
        BEGIN
            SET @StatusCode = -2;
            SET @ErrorMessage = 'No se encontró un siguiente nivel válido.';
            RETURN;
        END;

        -- Asignar los valores del siguiente turno a las variables de salida
        SELECT TOP 1
            @idWeekDayOut = idWeekDay,
            @weekDayOut = weekDay,
            @shiftNameOut = shiftName,
            @levelOut = level,
            @ShiftDateOut = @SystemDate
        FROM [StoreShiftConfiguration]
        WHERE level = @NextLevel AND [idStore] = @StoreID AND [posCode] = @numeroPos AND isActive = 1;

        -- Validar si se encontraron datos
        IF @idWeekDayOut IS NULL OR @weekDayOut IS NULL
        BEGIN
            SET @StatusCode = -3;
            SET @ErrorMessage = 'No se encontraron datos para el siguiente turno.';
            RETURN;
        END;

        -- Establecer éxito
        SET @StatusCode = 0;
        SET @ErrorMessage = 'Ejecución exitosa.';
    END TRY
    BEGIN CATCH
        -- Capturar errores
        SET @StatusCode = ERROR_NUMBER();
        SET @ErrorMessage = ERROR_MESSAGE();
    END CATCH;
	print(@StatusCode)
	print(@ErrorMessage)
END;

CREATE PROCEDURE [dbo].[OpenNewShift]
    @numeroPos NVARCHAR(5),
    @StoreID NVARCHAR(5),
    @EmployeeName NVARCHAR(50),
    @ShiftNumber NVARCHAR(5),
    @ImporteContado DECIMAL(18,2)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE 
        @NewShift NVARCHAR(5),
        @NextPosTransactionIDNumber NVARCHAR(50),
        @ExistingShiftID NVARCHAR(50),
        @ClosedShiftID NVARCHAR(50),
        @SeriesCode NVARCHAR(50),
        @LineNo INT;

    BEGIN TRANSACTION;

    BEGIN TRY
        -- 📌 Paso 1: Validar si ya hay un turno abierto
        SELECT @ExistingShiftID = [POS Transaction ID]
        FROM [TPV].[dbo].[POS Closed Shift]
        WHERE [Gas Station Code] = @StoreID
          AND [EmployeeName] = @EmployeeName
          AND [Shift Ending] IS NULL;

        IF @ExistingShiftID IS NOT NULL
        BEGIN
            PRINT 'Ya hay un turno abierto para este empleado en la estación.';
            ROLLBACK TRANSACTION;
            SELECT 0 AS Success, 'Ya hay un turno abierto para este empleado en la estación.' AS Message, NULL AS PosTransactionID, NULL AS NewShiftNumber;
            RETURN;
        END;

        -- 📌 Paso 1.1: Validar si ya existe un turno cerrado hoy
        SELECT TOP 1 @ClosedShiftID = [POS Transaction ID]
        FROM [TPV].[dbo].[POS Closed Shift]
        WHERE [Gas Station Code] = @StoreID
          AND [EmployeeName] = @EmployeeName
          AND [Shift] = @ShiftNumber
          AND CAST([Shift Starting] AS DATE) = CAST(GETDATE() AS DATE);

        IF @ClosedShiftID IS NOT NULL
        BEGIN
            PRINT 'Ya existe un turno cerrado hoy para Usuario: ' + @EmployeeName + '. Turno: ' + @ShiftNumber;
            ROLLBACK TRANSACTION;
            SELECT 0 AS Success, 'Ya existe un turno cerrado hoy para Usuario: ' + @EmployeeName + '. Turno: ' + @ShiftNumber AS Message, NULL AS PosTransactionID, NULL AS NewShiftNumber;
            RETURN;
        END;

        -- 📌 Paso 2: Obtener el número de transacción
        PRINT 'Paso 2: Obteniendo número de transacción';

        EXEC [dbo].[EINextPosTransactionIDNumber]
            @GasStationCode = @StoreID,
            @POSCode = @numeroPos,
            @SeriesCode = @SeriesCode OUTPUT,
            @LineNo = @LineNo OUTPUT,
            @NextPosTransactionIDNumber = @NextPosTransactionIDNumber OUTPUT;

        IF @NextPosTransactionIDNumber IS NULL
        BEGIN
            PRINT 'Error: No se pudo obtener el número de transacción.';
            ROLLBACK TRANSACTION;
            SELECT 0 AS Success, 'Error al generar número de transacción.' AS Message, NULL AS PosTransactionID, NULL AS NewShiftNumber;
            RETURN;
        END;

        PRINT 'Número de transacción obtenido: ' + ISNULL(@NextPosTransactionIDNumber, 'NULL');

        -- 📌 Paso 3: Obtener número de turno
        SET @NewShift = @ShiftNumber;

        -- 📌 Paso 4: Insertar el nuevo turno
        INSERT INTO [TPV].[dbo].[POS Closed Shift] 
           ([POS Transaction ID], [Gas Station Code], [POS Code], [Shift], 
            [idWeekDay], [Shift Starting], [Shift Ending], [ImporteContado], [EmployeeName])
        VALUES 
           (@NextPosTransactionIDNumber, @StoreID, @numeroPos, @NewShift, 
            0, GETDATE(), NULL, @ImporteContado, @EmployeeName);

        PRINT 'Turno insertado correctamente';

        -- 📌 Paso 5: Actualizar la serie
        UPDATE [No_ Series Line]
        SET [Last No_ Used] = @NextPosTransactionIDNumber,
            [Last Date Used] = GETDATE()
        WHERE [Series Code] = @SeriesCode
          AND [Line No_] = @LineNo
          AND [Gas Station Code] = @StoreID
          AND [POS Code] = @numeroPos;

        IF @@ROWCOUNT = 0
        BEGIN
            PRINT 'Error: No se pudo actualizar la serie.';
            ROLLBACK TRANSACTION;
            SELECT 0 AS Success, 'No se pudo actualizar la serie.' AS Message, NULL AS PosTransactionID, NULL AS NewShiftNumber;
            RETURN;
        END;

        COMMIT TRANSACTION;

        SELECT 1 AS Success, 'Turno abierto correctamente.' AS Message, @NextPosTransactionIDNumber AS PosTransactionID, @NewShift AS NewShiftNumber;
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;
        SELECT 0 AS Success, ERROR_MESSAGE() AS Message, NULL AS PosTransactionID, NULL AS NewShiftNumber;
    END CATCH;
END;

CREATE   PROCEDURE [dbo].[sp_CalcularTotalConDescuentoYISV]
    @codigo_cliente NVARCHAR(20),
    @codigo_item NVARCHAR(20),
    @cantidad DECIMAL(18,4),
    @tipo_isv DECIMAL(18,6),
    @precio_unitario DECIMAL(18,6) -- Precio unitario con ISV incluido
AS
BEGIN
    SET NOCOUNT ON;

    -- Variables
    DECLARE @porcentaje_descuento DECIMAL(18,4) = 0.0000;
    DECLARE @tiene_descuento NVARCHAR(2) = 'NO';

    -- Buscar descuento si existe
    SELECT TOP 1
        @porcentaje_descuento = porcentaje,
        @tiene_descuento = 'SI'
    FROM TPV.dbo.Descuentos
    WHERE codigo_cliente = @codigo_cliente AND codigo_item = @codigo_item;

    -- Variables internas
    DECLARE @precio_sin_isv_unitario DECIMAL(18,6);
    DECLARE @precio_descuento_unitario DECIMAL(18,6);
    DECLARE @nuevo_isv_unitario DECIMAL(18,6);
    DECLARE @total_final_unitario DECIMAL(18,6);

    DECLARE @total_sin_isv DECIMAL(18,6);
    DECLARE @total_descuento DECIMAL(18,6);
    DECLARE @total_isv DECIMAL(18,6);
    DECLARE @total_final DECIMAL(18,6);

    -- Paso 1: quitar ISV del precio
    SET @precio_sin_isv_unitario = @precio_unitario / (1 + (@tipo_isv / 100));

    -- Paso 2: aplicar descuento
    SET @precio_descuento_unitario = @precio_sin_isv_unitario * (1 - @porcentaje_descuento / 100);

    -- Paso 3: calcular nuevo ISV
    SET @nuevo_isv_unitario = @precio_descuento_unitario * (@tipo_isv / 100);

    -- Paso 4: total por unidad
    SET @total_final_unitario = @precio_descuento_unitario + @nuevo_isv_unitario;

    -- Paso 5: multiplicar por cantidad
    SET @total_sin_isv = @precio_sin_isv_unitario * @cantidad;
    SET @total_descuento = (@precio_sin_isv_unitario - @precio_descuento_unitario) * @cantidad;
    SET @total_isv = @nuevo_isv_unitario * @cantidad;
    SET @total_final = @total_final_unitario * @cantidad;

    -- Resultado final redondeado a 2 decimales
    SELECT
        @codigo_cliente AS codigo_cliente,
        @codigo_item AS codigo_item,
        @tiene_descuento AS tiene_descuento,
        CAST(@porcentaje_descuento AS DECIMAL(18,4)) AS porcentaje_descuento,
        CAST(@cantidad AS DECIMAL(18,4)) AS cantidad,
        CAST(@precio_unitario AS DECIMAL(18,4)) AS precio_unitario_con_isv,
        CAST(@precio_sin_isv_unitario AS DECIMAL(18,4)) AS precio_unitario_sin_isv,
        CAST(@precio_descuento_unitario AS DECIMAL(18,4)) AS precio_unitario_con_descuento,
        CAST(@nuevo_isv_unitario AS DECIMAL(18,4)) AS isv_unitario,
        CAST(@total_sin_isv AS DECIMAL(18,4)) AS total_sin_isv,
        CAST(@total_descuento AS DECIMAL(18,4)) AS total_descuento,
        CAST(@total_isv AS DECIMAL(18,4)) AS total_isv,
        CAST(@total_final AS DECIMAL(18,4)) AS total_final_con_isv;
END;

