CREATE PROCEDURE [dbo].[sp_GetSalesGrandTotalCL] 
    @FechaDesde DATE,
    @FechaHasta DATE,
    @Turno INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT 
        CAST(SUM(PSCL.[Amount]) AS DECIMAL(18,2)) AS GranTotal
    FROM [TPV].[dbo].[POS Transaction Log] PTL
    INNER JOIN [TPV].[dbo].[POS Sales Charge Line] PSCL 
        ON PTL.[POS Transaction ID] = PSCL.[POS Transaction ID]
    WHERE 
        CONVERT(DATE, PTL.[Shift Date]) BETWEEN @FechaDesde AND @FechaHasta
        AND (@Turno IS NULL OR @Turno = 0 OR PTL.[Shift No_] = @Turno)
END;

CREATE PROCEDURE [dbo].[sp_GetTotalSalesCombustibles] 
    @FechaDesde DATE,
    @FechaHasta DATE,
    @Turno INT
AS
BEGIN
    SET NOCOUNT ON; 

    -- Obtener la suma total de productos de QUIRY sin agrupar por bombero ni turno
    SELECT 
        ISNULL(SUM(PSL.[Quantity]), 0) AS TotalQuantity,
        ISNULL(SUM(PSL.[Amount Including VAT]), 0) AS TotalAmount
    FROM [TPV].[dbo].[POS Transaction Log] PTL
    INNER JOIN [TPV].[dbo].[POS Sales Line] PSL 
        ON PTL.[POS Transaction ID] = PSL.[POS Transaction ID]
    WHERE 
        CONVERT(DATE, PTL.[Shift Date]) BETWEEN @FechaDesde AND @FechaHasta
        AND PSL.[POS Sales Doc_ Type] IN ('1', '3')
        AND PSL.[POS Sales No_] IN ('COM00002', 'COM00003', 'COM00001', 'GAS00001')
        AND (@Turno IS NULL OR @Turno = 0 OR PTL.[Shift No_] = @Turno);
END;

CREATE PROCEDURE [dbo].[sp_GetTotalSalesOtrosProductos] 
    @FechaDesde DATE,
    @FechaHasta DATE,
    @Turno INT
AS
BEGIN
    SET NOCOUNT ON; 

    SELECT 
        ISNULL(SUM(PSL.[Quantity]), 0) AS TotalQuantity,
        ISNULL(SUM(PSL.[Amount Including VAT]), 0) AS TotalAmount
    FROM [TPV].[dbo].[POS Transaction Log] PTL
    INNER JOIN [TPV].[dbo].[POS Sales Line] PSL 
        ON PTL.[POS Transaction ID] = PSL.[POS Transaction ID]
    WHERE 
        CONVERT(DATE, PTL.[Shift Date]) BETWEEN @FechaDesde AND @FechaHasta
        AND PSL.[POS Sales Doc_ Type] IN ('1', '3')
        AND PSL.[POS Sales No_] NOT IN ('COM00002', 'COM00003', 'COM00001', 'GAS00001')
        AND (@Turno IS NULL OR @Turno = 0 OR PTL.[Shift No_] = @Turno);
END;

CREATE PROCEDURE [dbo].[sp_InsertarPOSSalesHeaderLeal]
    @PosTransactionID NVARCHAR(20),
    @IdTransaccionLeal NVARCHAR(20),
    @Puntos INT,
    @PuntosActivos INT,
    @Tipo TINYINT,
    @DNI NVARCHAR(50),
    @Nombre NVARCHAR(100),
    @IDAleatorio BIGINT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    INSERT INTO dbo.POSSalesHeaderLeal
    (
        [POS Transaction ID],
        [Id_TransaccionLeal],
        [Puntos],
        [PuntosActivos],
        [Tipo],
        [DNI],
        [Nombre],
        [IDAleatorio]
    )
    VALUES
    (
        @PosTransactionID,
        @IdTransaccionLeal,
        @Puntos,
        @PuntosActivos,
        @Tipo,
        @DNI,
        @Nombre,
        @IDAleatorio
    );

    SELECT 'OK' AS Resultado;
END

 CREATE PROCEDURE [dbo].[UpdateCustomerInfo]
    @NewName VARCHAR(MAX),
    @NewRTN VARCHAR(50),
    @oldNo VARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM [Customer] WHERE [No_] = @oldNo)
    BEGIN
        UPDATE [Customer]
        SET [Name] = @NewName,
            [No_] = @NewRTN,
            [VAT Registration No_] = @NewRTN,
            DateUpdate = GETDATE()
        WHERE [VAT Registration No_] = @oldNo;

        SELECT 
            'Cambio realizado exitosamente' AS Message,
            1 AS Success;
    END
    ELSE
    BEGIN
        SELECT 
            'El cliente no fue encontrado.' AS Message,
            0 AS Success;
    END
END;

CREATE PROCEDURE [dbo].[updateStatusTransactionLog]
    @POSTransactionID NVARCHAR(50)
AS
BEGIN
    -- Manejo de errores
    BEGIN TRY
        -- Actualiza el estado en la tabla POS Transaction Log
        UPDATE [POS Transaction Log]
        SET [Status] = 1
        WHERE [POS Transaction ID] = @POSTransactionID AND [Status] <> 1;

        -- Devuelve el número de filas afectadas
        RETURN @@ROWCOUNT;
    END TRY
    BEGIN CATCH
        -- Manejo de errores
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        PRINT 'Error occurred: ' + @ErrorMessage;
        RETURN -1; -- Indica error
    END CATCH;
END;

CREATE PROCEDURE [dbo].[UpdateStoreLines]
  @NewShiftDate DATE,
  @NewShiftNumber INT, 
  @NewTransactionID NVARCHAR(50),
  @StoreID NVARCHAR(5),
  @PosCode NVARCHAR(5),
  @ReturnValue INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRANSACTION;

    UPDATE [StoreLines]
    SET [ShiftDate] = @NewShiftDate,
        [ShiftNumber] = @NewShiftNumber,
        [POS Transaction ID] = @NewTransactionID
    WHERE [StoreID] = @StoreID AND [PosCode] = @PosCode;

    IF @@ROWCOUNT > 0
    BEGIN
        COMMIT;
        SET @ReturnValue = 1; -- Indica que la actualización fue exitosa
    END
    ELSE
    BEGIN
        ROLLBACK;
        SET @ReturnValue = 0; -- Indica que la actualización falló
    END;
END;

CREATE PROCEDURE [dbo].[UpdateStoreShift]
    @shift INT,
    @startTime TIME,
    @endTime TIME,
    @success BIT OUTPUT
AS
BEGIN
    -- Inicializar la variable de éxito como 0 (falso) por defecto
    SET @success = 0;

    -- Actualizar los valores de StartTime y EndTime en la tabla StoreShift
    UPDATE StoreShift
    SET [StartTime] = @startTime,
        [EndTime] = @endTime
    WHERE [Shift] = @shift;

    -- Verificar si la actualización fue exitosa
    IF @@ROWCOUNT > 0
    BEGIN
        -- Si se actualizó al menos una fila, establecer la variable de éxito como 1 (verdadero)
        SET @success = 1;
    END;
END;

CREATE PROCEDURE [dbo].[UpdateTaxDocuments]
    @LineNo INT,
    @SeriesCode NVARCHAR(50),
    @GasStationCode NVARCHAR(50),
    @POSCode NVARCHAR(50),
    @WarningNo NVARCHAR(50),
    @IncrementByNo INT,
    @LastNoUsed NVARCHAR(50),
    @Open BIT,
    @CAI NVARCHAR(50),
    @RangoDesde NVARCHAR(50),
    @RangoHasta NVARCHAR(50),
    @FechaVenceRango DATE
AS
BEGIN
    -- Evitar errores por cambios imprevistos en la base de datos
    SET NOCOUNT ON;

    -- Actualizar los campos de la tabla
    UPDATE [No_ Series Line]
    SET 
        [Series Code] = @SeriesCode,

        [Starting Date] = GETDATE(),
        [Starting No_] = @RangoDesde,
        [Ending No_] = @RangoHasta,
        [Warning No_] = @WarningNo,
        [Increment-by No_] = @IncrementByNo,
        [Last No_ Used] = @LastNoUsed,
        [Open] = @Open,
        [CAI] = @CAI,
        [Rango Desde] = @RangoDesde,
        [Rango Hasta] = @RangoHasta,
        [Fecha Vence Rango] = @FechaVenceRango
    WHERE [Line No_] = @LineNo AND  [Gas Station Code] = @GasStationCode AND  [POS Code] = @POSCode AND [Series Code]=@SeriesCode;

	 -- Retornar el registro actualizado
    SELECT * FROM [No_ Series Line]
    WHERE [Line No_] = @LineNo AND [Gas Station Code] = @GasStationCode AND [POS Code] = @POSCode AND [Series Code]=@SeriesCode;
END;
